#!/usr/bin/env node
/**
 * Applies a debug placement-editor export (street-edits-*.json, see src/Utils/PlacementEdit.ts)
 * to src/assets/data/street-placement.ipl.ts.
 *
 *   node tools/ipl/apply_street_edits.mjs <street-edits.json> [--dry]
 *
 * - 'ipl' edits: every line in `ids` gets `to.pos` / `to.rot`. A line whose current pos/rot no
 *   longer matches `from` is skipped (the export is stale) and reported.
 * - 'plan.building' / 'plan.prop' edits live in the road plan (src/assets/data/road-plans/*.ts,
 *   partly generated by spreads) — they are only listed, for a hand edit.
 * Exit code 1 when anything was skipped or left for a hand edit.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const IPL = path.join(ROOT, 'src/assets/data/street-placement.ipl.ts');

const [, , jsonPath, ...flags] = process.argv;
if (!jsonPath) {
    console.error('usage: node tools/ipl/apply_street_edits.mjs <street-edits.json> [--dry]');
    process.exit(2);
}
const dry = flags.includes('--dry');
const doc = JSON.parse(fs.readFileSync(jsonPath, 'utf8'));
if (doc.kind !== 'dict-three/street-placement-edits' || doc.version !== 1) {
    console.error(`not a street-placement-edits v1 file: ${jsonPath}`);
    process.exit(2);
}

const src = fs.readFileSync(IPL, 'utf8');
const eol = src.includes('\r\n') ? '\r\n' : '\n';
const lines = src.split(eol);
const LINE = /^(\s*\{ id: )(\d+)(, modelName: '[^']+', pos: )\[([^\]]+)\](, rot: )\[([^\]]+)\](.*)$/;
const byId = new Map();
lines.forEach((l, n) => {
    const m = LINE.exec(l);
    if (m) byId.set(Number(m[2]), { n, m });
});

const nums = (s) => s.split(',').map(Number);
const close = (a, b, eps) => a.length === b.length && a.every((v, i) => Math.abs(v - b[i]) <= eps);
const fmt = (v) => `[${v.map((x) => String(Object.is(x, -0) ? 0 : x)).join(', ')}]`;

let patched = 0;
const problems = [];
for (const e of doc.edits) {
    if (e.source !== 'ipl') {
        problems.push(`${e.key} (${e.models.join(' / ')}): ${e.source} index ${e.index} -> pos ${fmt(e.to.pos)} yaw ${e.to.yawDeg}° — edit the road plan by hand`);
        continue;
    }
    for (const id of e.ids ?? [e.id]) {
        const hit = byId.get(id);
        if (!hit) { problems.push(`${e.key}: IPL id ${id} not found`); continue; }
        const { n, m } = hit;
        if (!close(nums(m[4]), e.from.pos, 1e-3) || !close(nums(m[6]), e.from.rot, 1e-5)) {
            problems.push(`${e.key}: IPL id ${id} is at ${fmt(nums(m[4]))} rot ${fmt(nums(m[6]))}, export expected ${fmt(e.from.pos)} — stale, skipped`);
            continue;
        }
        lines[n] = `${m[1]}${m[2]}${m[3]}${fmt(e.to.pos)}${m[5]}${fmt(e.to.rot)}${m[7]}`;
        patched++;
        console.log(`${String(id).padStart(4)} ${e.models.join(' / ')}: ${fmt(e.from.pos)} -> ${fmt(e.to.pos)}${e.delta.yawDeg ? `, yaw ${e.from.yawDeg}° -> ${e.to.yawDeg}°` : ''}`);
    }
}

if (!dry && patched > 0) fs.writeFileSync(IPL, lines.join(eol));
console.log(`${dry ? '[dry] ' : ''}${patched} IPL line(s) ${dry ? 'would be ' : ''}patched`);
for (const p of problems) console.warn(`! ${p}`);
process.exit(problems.length ? 1 : 0);
